1	/**
2	 * Split Payment routes
3	 *
4	 * POST /api/games/checkout-split  — host initiates a split booking + game + pays their share
5	 * GET  /api/bookings/share/:token — public: get split booking info (for invite page)
6	 * POST /api/bookings/share/:token/checkout — invitee pays their share
7	 * GET  /api/bookings/:bookingId/split-status — host/participant: see all payment statuses
8	 */
9	import { Router, type IRouter } from "express";
10	import { and, eq, ne, sql } from "drizzle-orm";
11	import {
12	  db,
13	  bookingsTable,
14	  courtsTable,
15	  facilitiesTable,
16	  gamesTable,
17	  gameParticipantsTable,
18	  userProfilesTable,
19	  userSportProfilesTable,
20	  courtPricingTable,
21	  courtBlockedSlotsTable,
22	} from "@workspace/db";
23	
24	import { requireAuth, getCurrentUserId } from "../lib/auth";
25	import { getAuth } from "@clerk/express";
26	import { getUncachableStripeClient } from "../stripeClient";
27	import { logger } from "../lib/logger";
28	import { sendSplitBookingCreatedEmail, sendSplitPlayerJoinedEmail, sendSplitParticipantConfirmationEmail } from "../lib/email";
29	import { sendNotification } from "../lib/notify";
30	import { z } from "zod";
31	import crypto from "node:crypto";
32	
33	const router: IRouter = Router();
34	
35	// ─── Helpers ─────────────────────────────────────────────────────────────────
36	
37	function toMin(t: string): number {
38	  const [h, m] = t.split(":").map(Number);
39	  return h * 60 + m;
40	}
41	
42	function slotsBetween(startTime: string, endTime: string): string[] {
43	  const slots: string[] = [];
44	  let cur = toMin(startTime);
45	  const end = toMin(endTime);
46	  while (cur < end) {
47	    const h = Math.floor(cur / 60).toString().padStart(2, "0");
48	    const m = (cur % 60).toString().padStart(2, "0");
49	    slots.push(`${h}:${m}`);
50	    cur += 30;
51	  }
52	  return slots;
53	}
54	
55	// ─── POST /api/games/checkout-split ──────────────────────────────────────────
56	
57	const SplitCheckoutBody = z.object({
58	  courtId: z.number().int().positive(),
59	  date: z.string().regex(/^\d{4}-\d{2}-\d{2}$/),
60	  startTime: z.string().regex(/^\d{2}:\d{2}$/),
61	  endTime: z.string().regex(/^\d{2}:\d{2}$/),
62	  totalSlots: z.number().int().min(2).max(8),
63	  sport: z.string().min(1),
64	  skillLevel: z.string().optional().default("any"),
65	  description: z.string().optional(),
66	  customerName: z.string().min(1),
67	  customerEmail: z.string().email(),
68	  customerPhone: z.string().optional(),
69	  // Open match fields
70	  isPublic: z.boolean().optional().default(false),
71	  minSkillLevel: z.number().min(0).max(10).optional(),
72	  maxSkillLevel: z.number().min(0).max(10).optional(),
73	  matchType: z.enum(["casual", "competitive"]).optional().default("casual"),
74	  // Upgrade flow: link an existing casual game instead of creating a new one
75	  linkGameId: z.number().int().positive().optional(),
76	});
77	
78	router.post("/games/checkout-split", requireAuth, async (req, res): Promise<void> => {
79	  const userId = getCurrentUserId(req)!;
80	  const parsed = SplitCheckoutBody.safeParse(req.body);
81	  if (!parsed.success) {
82	    res.status(400).json({ error: parsed.error.message });
83	    return;
84	  }
85	
86	  const {
87	    courtId, date, startTime, endTime, totalSlots, sport, skillLevel, description,
88	    customerName, customerEmail, customerPhone,
89	    isPublic, minSkillLevel, maxSkillLevel, matchType,
90	    linkGameId,
91	  } = parsed.data;
92	
93	  const reqStartMin = toMin(startTime);
94	  const reqEndMin = toMin(endTime);
95	  if (reqEndMin <= reqStartMin) {
96	    res.status(400).json({ error: "endTime must be after startTime" });
97	    return;
98	  }
99	
100	  // ── Fetch court and facility ──────────────────────────────────────────────
101	  const [courtRow] = await db
102	    .select({ court: courtsTable, facility: facilitiesTable })
103	    .from(courtsTable)
104	    .leftJoin(facilitiesTable, eq(courtsTable.facilityId, facilitiesTable.id))
105	    .where(eq(courtsTable.id, courtId));
106	
107	  if (!courtRow?.court) {
108	    res.status(404).json({ error: "Court not found" });
109	    return;
110	  }
111	
112	  const { court, facility } = courtRow;
113	
114	  // ── Server-side price calculation ─────────────────────────────────────────
115	  const dateObj = new Date(`${date}T12:00:00`);
116	  const dayOfWeek = dateObj.getDay();
117	
118	  const pricingEntries = await db.select()
119	    .from(courtPricingTable)
120	    .where(and(
121	      eq(courtPricingTable.courtId, courtId),
122	      eq(courtPricingTable.dayOfWeek, dayOfWeek),
123	    ));
124	
125	  const pricingMap = new Map(pricingEntries.map(e => [e.startTime, Number(e.price)]));
126	  const defaultSlotPrice = Number(court.pricePerHour) / 2;
127	
128	  const slots = slotsBetween(startTime, endTime);
129	  let courtPrice = 0;
130	  for (const slotStart of slots) {
131	    courtPrice += pricingMap.has(slotStart) ? pricingMap.get(slotStart)! : defaultSlotPrice;
132	  }
133	
134	  const totalPrice = courtPrice;
135	  const pricePerSlot = Math.round((totalPrice / totalSlots) * 100) / 100;
136	  const durationMinutes = reqEndMin - reqStartMin;
137	
138	  // ── Conflict check ────────────────────────────────────────────────────────
139	  const conflictingBookings = await db
140	    .select({ startTime: bookingsTable.startTime, endTime: bookingsTable.endTime })
141	    .from(bookingsTable)
142	    .where(and(
143	      eq(bookingsTable.courtId, courtId),
144	      eq(bookingsTable.date, date),
145	      sql`${bookingsTable.status} IN ('confirmed', 'blocked', 'awaiting_players')`,
146	    ));
147	
148	  const recentPending = await db
149	    .select({ startTime: bookingsTable.startTime, endTime: bookingsTable.endTime })
150	    .from(bookingsTable)
151	    .where(and(
152	      eq(bookingsTable.courtId, courtId),
153	      eq(bookingsTable.date, date),
154	      eq(bookingsTable.status, "pending"),
155	      sql`${bookingsTable.createdAt} > NOW() - INTERVAL '15 minutes'`,
156	    ));
157	
158	  const allConflicting = [...conflictingBookings, ...recentPending];
159	  for (const b of allConflicting) {
160	    const bStart = toMin(b.startTime);
161	    const bEnd = toMin(b.endTime);
162	    if (reqStartMin < bEnd && reqEndMin > bStart) {
163	      res.status(409).json({ error: "Pasirinktas laikas užimtas", code: "SLOT_UNAVAILABLE" });
164	      return;
165	    }
166	  }
167	
168	  // Also check blocked slots
169	  const blockedSlots = await db
170	    .select({ startTime: courtBlockedSlotsTable.startTime, endTime: courtBlockedSlotsTable.endTime })
171	    .from(courtBlockedSlotsTable)
172	    .where(and(
173	      eq(courtBlockedSlotsTable.courtId, courtId),
174	      eq(courtBlockedSlotsTable.date, date),
175	    ));
176	
177	  for (const b of blockedSlots) {
178	    const bStart = toMin(b.startTime);
179	    const bEnd = toMin(b.endTime);
180	    if (reqStartMin < bEnd && reqEndMin > bStart) {
181	      res.status(409).json({ error: "Pasirinktas laikas užblokuotas", code: "SLOT_BLOCKED" });
182	      return;
183	    }
184	  }
185	
186	  // ── Create booking ────────────────────────────────────────────────────────
187	  const splitInviteToken = crypto.randomBytes(20).toString("hex");
188	  const datetime = `${date}T${startTime}:00`;
189	
190	  const [booking] = await db.insert(bookingsTable).values({
191	    courtId,
192	    bookerUserId: userId,
193	    customerName,
194	    customerEmail,
195	    customerPhone: customerPhone ?? null,
196	    date,
197	    startTime,
198	    endTime,
199	    totalPrice: String(totalPrice),
200	    status: "pending",
201	    isSplit: true,
202	    totalSlots,
203	    pricePerSlot: String(pricePerSlot),
204	    splitInviteToken,
205	  }).returning();
206	
207	  // ── Create or reuse linked game ───────────────────────────────────────────
208	  let gameId: number;
209	  if (linkGameId) {
210	    // Upgrade flow: skip game creation; the existing game will be updated after payment confirms.
211	    gameId = linkGameId;
212	  } else {
213	    const [newGame] = await db.insert(gamesTable).values({
214	      creatorUserId: userId,
215	      creatorName: customerName,
216	      creatorEmail: customerEmail,
217	      sport,
218	      city: facility?.city ?? "",
219	      placeName: facility?.name ?? court.name,
220	      facilityId: facility?.id ?? null,
221	      courtId,
222	      bookingId: booking.id,
223	      playersNeeded: totalSlots,
224	      skillLevel: skillLevel ?? "any",
225	      datetime,
226	      durationMinutes,
227	      description: description ?? null,
228	      status: "pending_payment",
229	      matchType: matchType ?? "casual",
230	      isPrivate: !isPublic,
231	      visibility: isPublic ? "public" : "private",
232	      minSkillLevel: isPublic ? (minSkillLevel ?? null) : null,
233	      maxSkillLevel: isPublic ? (maxSkillLevel ?? null) : null,
234	      requiresApproval: false,
235	      teamCount: 2,
236	    }).returning();
237	    gameId = newGame.id;
238	  }
239	
240	  // ── Add host as participant (pending payment) ─────────────────────────────
241	  // For the upgrade flow, update the existing host participant to track payment;
242	  // for the normal flow, insert a fresh record.
243	  let hostParticipant: typeof gameParticipantsTable.$inferSelect;
244	  if (linkGameId) {
245	    const [existing] = await db
246	      .select()
247	      .from(gameParticipantsTable)
248	      .where(and(eq(gameParticipantsTable.gameId, linkGameId), eq(gameParticipantsTable.userId, userId)));
249	    if (existing) {
250	      [hostParticipant] = await db
251	        .update(gameParticipantsTable)
252	        .set({ paymentStatus: "pending" })
253	        .where(eq(gameParticipantsTable.id, existing.id))
254	        .returning();
255	    } else {
256	      [hostParticipant] = await db.insert(gameParticipantsTable).values({
257	        gameId: linkGameId,
258	        userId,
259	        userName: customerName,
260	        userEmail: customerEmail,
261	        status: "joined",
262	        source: "join_request",
263	        paymentStatus: "pending",
264	      }).returning();
265	    }
266	  } else {
267	    [hostParticipant] = await db.insert(gameParticipantsTable).values({
268	      gameId,
269	      userId,
270	      userName: customerName,
271	      userEmail: customerEmail,
272	      status: "joined",
273	      source: "join_request",
274	      paymentStatus: "pending",
275	    }).returning();
276	  }
277	
278	  // ── Create Stripe checkout for host's share ───────────────────────────────
279	  const origin = req.get("origin") ?? req.get("host") ?? "https://korts.lt";
280	  const base = process.env.BASE_PATH ?? "";
281	  const successUrl = `${origin}${base}/booking-confirmed?id=${booking.id}&split=1`;
282	  const cancelUrl = `${origin}${base}/courts/${courtId}?booking_cancelled=1&bookingId=${booking.id}`;
283	
284	  let checkoutUrl: string;
285	
286	  try {
287	    const stripe = await getUncachableStripeClient();
288	
289	    // Resolve Connect account
290	    let connectAccountId: string | null = null;
291	    if (facility?.ownerUserId) {
292	      const [profile] = await db
293	        .select({ stripeAccountId: userProfilesTable.stripeAccountId, status: userProfilesTable.stripeAccountStatus })
294	        .from(userProfilesTable)
295	        .where(eq(userProfilesTable.userId, facility.ownerUserId));
296	      if (profile?.stripeAccountId && profile.status === "active") {
297	        connectAccountId = profile.stripeAccountId;
298	      }
299	    }
300	
301	    const amountCents = Math.round(pricePerSlot * 100);
302	    const sessionParams: any = {
303	      payment_method_types: ["card"],
304	      line_items: [{
305	        price_data: {
306	          currency: "eur",
307	          product_data: {
308	            name: `${court.name} – mokėjimo dalis (1/${totalSlots})`,
309	            description: `${date} · ${startTime}–${endTime}`,
310	          },
311	          unit_amount: amountCents,
312	        },
313	        quantity: 1,
314	      }],
315	      mode: "payment",
316	      success_url: `${successUrl}&session_id={CHECKOUT_SESSION_ID}`,
317	      cancel_url: cancelUrl,
318	      metadata: {
319	        bookingId: String(booking.id),
320	        splitParticipantId: String(hostParticipant.id),
321	        ...(linkGameId ? { linkGameId: String(linkGameId) } : {}),
322	      },
323	      customer_email: customerEmail,
324	      locale: "lt",
325	    };
326	
327	    if (connectAccountId) {
328	      const feeAmount = Math.round(amountCents * 5 / 100);
329	      sessionParams.payment_intent_data = {
330	        application_fee_amount: feeAmount,
331	        transfer_data: { destination: connectAccountId },
332	      };
333	    }
334	
335	    const session = await stripe.checkout.sessions.create(sessionParams);
336	
337	    // Store session ids
338	    await db.update(bookingsTable)
339	      .set({ stripeSessionId: session.id })
340	      .where(eq(bookingsTable.id, booking.id));
341	
342	    await db.update(gameParticipantsTable)
343	      .set({ stripeSessionId: session.id })
344	      .where(eq(gameParticipantsTable.id, hostParticipant.id));
345	
346	    checkoutUrl = session.url!;
347	
348	  } catch (err: any) {
349	    if (err?.message?.includes("Stripe not configured") || err?.type === "StripeAuthenticationError") {
350	      // Mock checkout for dev
351	      const mockId = `mock_split_${booking.id}_${Date.now()}`;
352	      await db.update(bookingsTable)
353	        .set({ stripeSessionId: mockId, status: "awaiting_players" })
354	        .where(eq(bookingsTable.id, booking.id));
355	      await db.update(gameParticipantsTable)
356	        .set({ stripeSessionId: mockId, paymentStatus: "paid" })
357	        .where(eq(gameParticipantsTable.id, hostParticipant.id));
358	      if (linkGameId) {
359	        await db.update(gamesTable)
360	          .set({
361	            bookingId: booking.id,
362	            facilityId: facility?.id ?? null,
363	            courtId,
364	            status: "awaiting_players",
365	            datetime: `${booking.date}T${booking.startTime}:00`,
366	            durationMinutes: toMin(booking.endTime) - toMin(booking.startTime),
367	          })
368	          .where(eq(gamesTable.id, linkGameId));
369	      } else {
370	        await db.update(gamesTable)
371	          .set({ status: "awaiting_players" })
372	          .where(eq(gamesTable.id, gameId));
373	      }
374	      checkoutUrl = `${successUrl}&session_id=${mockId}`;
375	    } else {
376	      logger.error({ err }, "Failed to create Stripe session for split checkout");
377	      if (!linkGameId) {
378	        // Rollback only applies when we created a new game
379	        await db.update(bookingsTable).set({ status: "cancelled" }).where(eq(bookingsTable.id, booking.id));
380	        await db.delete(gamesTable).where(eq(gamesTable.id, gameId));
381	      }
382	      res.status(500).json({ error: "Failed to create payment session" });
383	      return;
384	    }
385	  }
386	
387	  res.status(201).json({
388	    url: checkoutUrl,
389	    bookingId: booking.id,
390	    gameId,
391	    shareToken: splitInviteToken,
392	    pricePerSlot,
393	    totalPrice,
394	    totalSlots,
395	  });
396	});
