630	    guestName = (req.body?.guestName as string | undefined)?.trim() ?? null;
631	    guestEmail = (req.body?.guestEmail as string | undefined)?.trim() ?? null;
632	    if (!guestName || !guestEmail) {
633	      res.status(400).json({ error: "Vardas ir el. paštas privalomi" });
634	      return;
635	    }
636	    if (!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(guestEmail)) {
637	      res.status(400).json({ error: "Neteisingas el. pašto adresas" });
638	      return;
639	    }
640	  }
641	
642	  const rows = await db
643	    .select({ booking: bookingsTable, court: courtsTable, facility: facilitiesTable })
644	    .from(bookingsTable)
645	    .leftJoin(courtsTable, eq(bookingsTable.courtId, courtsTable.id))
646	    .leftJoin(facilitiesTable, eq(courtsTable.facilityId, facilitiesTable.id))
647	    .where(eq(bookingsTable.splitInviteToken, token));
648	
649	  if (!rows[0]) { res.status(404).json({ error: "Invite link not found" }); return; }
650	
651	  const { booking, court, facility } = rows[0];
652	
653	  if (!booking.isSplit) { res.status(400).json({ error: "Not a split booking" }); return; }
654	  if (booking.status === "cancelled") { res.status(410).json({ error: "Booking was cancelled" }); return; }
655	  if (booking.status === "confirmed") { res.status(409).json({ error: "Booking fully paid" }); return; }
656	
657	  // Prevent authenticated host from joining again via invite link
658	  if (!isGuest && booking.bookerUserId === userId) {
659	    res.status(409).json({ error: "Tu jau esi šio žaidimo organizatorius" });
660	    return;
661	  }
662	
663	  // Get linked game
664	  const [game] = await db.select().from(gamesTable).where(eq(gamesTable.bookingId, booking.id));
665	  if (!game) { res.status(500).json({ error: "Game not found" }); return; }
666	
667	  // Get existing participants
668	  const existingParticipants = await db
669	    .select()
670	    .from(gameParticipantsTable)
671	    .where(and(
672	      eq(gameParticipantsTable.gameId, game.id),
673	      eq(gameParticipantsTable.status, "joined"),
